using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "AuspiciousChantingCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Sothis/AuspiciousChantingCustomDescription", order = 0)]
public class AuspiciousChantingCustomDescription : CustomBattleActionDescription
{
	[SerializeField]
	private NonNormalChantingCustomDescription nonNormalChantingCustomDescription;

	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		AuspiciousChantingAction auspiciousChantingAction = battleAction as AuspiciousChantingAction;
		return nonNormalChantingCustomDescription.GetActionDescription(amountModified, battleAction) + "\n" + auspiciousChantingAction.DrawAction.GetActionDescription(GetAmountWithoutEquation(amountModified));
	}
}
